   197→// writeEnvFile writes KEY=value pairs to .env, sorted by key.
   198→func writeEnvFile(root *os.Root, envVars map[string]string) error {
   199→	f, err := root.OpenFile(".env", os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
   200→	if err != nil {
   201→		return err
   202→	}
   203→	defer f.Close()
   204→	for _, key := range slices.Sorted(maps.Keys(envVars)) {
   205→		if _, err := fmt.Fprintf(f, "%s=%s\n", key, envVars[key]); err != nil {
   206→			return err
   207→		}
   208→	}
   209→	return nil
   210→}
   211→
   212→// writeSecret writes a docker secret value to a file in the secrets root.
   213→func writeSecret(root *os.Root, name, value string) error {
   214→	f, err := root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
   215→	if err != nil {
   216→		return err
   217→	}
   218→	defer f.Close()
   219→	_, err = f.WriteString(value)
   220→	return err
   221→}
