   332→// detectServiceInfo parses a compose file to find the main service name and port.
   333→// Prefers a service named "app", then appName, then the first alphabetically.
   334→func detectServiceInfo(composeFilePath, appName string) (serviceName, port string, err error) {
   335→	data, err := os.ReadFile(composeFilePath)
   336→	if err != nil {
   337→		return "", "", err
   338→	}
   339→
   340→	var mc minimalCompose
   341→	if err := yaml.Unmarshal(data, &mc); err != nil {
   342→		return "", "", err
   343→	}
   344→
   345→	if len(mc.Services) == 0 {
   346→		return "app", "3000", nil
   347→	}
   348→
   349→	names := slices.Sorted(maps.Keys(mc.Services))
   350→	serviceName = names[0]
   351→	for _, n := range names {
   352→		if n == "app" || n == appName {
   353→			serviceName = n
   354→			break
   355→		}
   356→	}
   357→
   358→	port = extractFirstPort(mc.Services[serviceName])
   359→	if port == "" {
   360→		port = "3000"
   361→	}
   362→	return serviceName, port, nil
   363→}
   364→
   365→func extractFirstPort(svc minimalService) string {
   366→	for _, v := range svc.Expose {
   367→		if p := portFromAny(v); p != "" {
   368→			return p
   369→		}
   370→	}
   371→	for _, v := range svc.Ports {
   372→		if p := portFromAny(v); p != "" {
   373→			return p
   374→		}
   375→	}
   376→	return ""
   377→}
   378→
   379→func portFromAny(v any) string {
   380→	switch val := v.(type) {
   381→	case string:
   382→		// "3000", "3000:3000", "0.0.0.0:80:3000"
   383→		parts := strings.Split(val, ":")
   384→		p := strings.TrimSpace(parts[len(parts)-1])
   385→		return p
   386→	case int:
   387→		return fmt.Sprintf("%d", val)
   388→	case map[string]any:
   389→		// long form: {target: 3000, published: 3000}
   390→		if t, ok := val["target"]; ok {
   391→			return portFromAny(t)
   392→		}
   393→	}
   394→	return ""
   395→}
   396→
   397→// deepMerge recursively merges overlay into base. Overlay wins on conflict
   398→// unless both values are maps, in which case they are merged recursively.
   399→func deepMerge(base, overlay map[string]any) map[string]any {
   400→	result := make(map[string]any, len(base))
   401→	for k, v := range base {
   402→		result[k] = v
   403→	}
   404→	for k, v := range overlay {
   405→		if bv, ok := result[k]; ok {
   406→			if bMap, ok := bv.(map[string]any); ok {
   407→				if oMap, ok := v.(map[string]any); ok {
   408→					result[k] = deepMerge(bMap, oMap)
   409→					continue
   410→				}
   411→			}
   412→		}
   413→		result[k] = v
   414→	}
   415→	return result
   416→}
