   139→func (m *CaddyManager) listProxiedDomains(ctx context.Context) ([]ProxiedDomain, error) {
   140→	out, err := runCmdOutput(ctx, "docker", "ps", "--filter", "network=caddy", "-q", "--no-trunc")
   141→	if err != nil {
   142→		return nil, err
   143→	}
   144→	ids := strings.Fields(strings.TrimSpace(out))
   145→	if len(ids) == 0 {
   146→		return nil, nil
   147→	}
   148→
   149→	args := append([]string{"inspect"}, ids...)
   150→	out, err = runCmdOutput(ctx, "docker", args...)
   151→	if err != nil {
   152→		return nil, err
   153→	}
   154→
   155→	type containerInfo struct {
   156→		Name   string `json:"Name"`
   157→		Config struct {
   158→			Labels map[string]string `json:"Labels"`
   159→		} `json:"Config"`
   160→	}
   161→
   162→	var containers []containerInfo
   163→	if err := json.Unmarshal([]byte(out), &containers); err != nil {
   164→		return nil, fmt.Errorf("parsing docker inspect: %w", err)
   165→	}
   166→
   167→	var domains []ProxiedDomain
   168→	for _, c := range containers {
   169→		domain, ok := c.Config.Labels["caddy"]
   170→		if !ok || domain == "" {
   171→			continue
   172→		}
   173→		name := strings.TrimPrefix(c.Name, "/")
   174→		domains = append(domains, ProxiedDomain{
   175→			Domain:   domain,
   176→			Upstream: parseCaddyUpstream(name, c.Config.Labels),
   177→		})
   178→	}
   179→	return domains, nil
   180→}
