   182→var upstreamsPortRe = regexp.MustCompile(`\{\{upstreams\s+(\d+)\}\}`)
   183→
   184→func parseCaddyUpstream(containerName string, labels map[string]string) string {
   185→	if to, ok := labels["caddy.reverse_proxy.to"]; ok {
   186→		to = strings.Replace(to, "host.docker.internal:", "host:", 1)
   187→		return to + " (herald)"
   188→	}
   189→	if rp, ok := labels["caddy.reverse_proxy"]; ok {
   190→		if m := upstreamsPortRe.FindStringSubmatch(rp); len(m) >= 2 {
   191→			return containerName + ":" + m[1]
   192→		}
   193→	}
   194→	return containerName
   195→}
