   108→// Update pulls the IaC repo, sets up the stack if needed, and runs the update script.
   109→func (m *StackManager) Update(ctx context.Context, stackName string) error {
   110→	stack, ok := m.Config.Stacks[stackName]
   111→	if !ok {
   112→		return fmt.Errorf("stack %q not found in config", stackName)
   113→	}
   114→
   115→	start := time.Now()
   116→	m.Logger.Info("stack update started", "stack", stackName)
   117→
   118→	if err := m.gitPull(ctx); err != nil {
   119→		return fmt.Errorf("pulling IaC repo: %w", err)
   120→	}
   121→
   122→	if stack.UpdateScript == "" {
   123→		return fmt.Errorf("stack %q has no update_script configured", stackName)
   124→	}
   125→	scriptPath := filepath.Join(m.repoDir(), stack.UpdateScript)
   126→	if _, err := os.Stat(scriptPath); err != nil {
   127→		return fmt.Errorf("update script %q not found in server repo", stack.UpdateScript)
   128→	}
