   398→// --- Streaming command runner ---
   399→
   400→// runStreamCmd executes a command, streaming stdout/stderr to the logger in real-time.
   401→func runStreamCmd(ctx context.Context, logger *slog.Logger, dir, name string, args ...string) error {
   402→	cmd := exec.CommandContext(ctx, name, args...)
   403→	if dir != "" {
   404→		cmd.Dir = dir
   405→	}
   406→
   407→	outWriter := &lineWriter{logger: logger, cmd: name, level: slog.LevelInfo}
   408→	errWriter := &lineWriter{logger: logger, cmd: name, level: slog.LevelWarn}
   409→	cmd.Stdout = outWriter
   410→	cmd.Stderr = errWriter
   411→
   412→	start := time.Now()
   413→	runErr := cmd.Run()
   414→	outWriter.flush()
   415→	errWriter.flush()
   416→	dur := time.Since(start).Round(time.Millisecond)
   417→
   418→	if runErr != nil {
   419→		return fmt.Errorf("%s: %w (duration: %s)", name, runErr, dur)
   420→	}
   421→	logger.Info("command completed", "cmd", name, "duration", dur)
   422→	return nil
   423→}
   424→
   425→// lineWriter buffers by newline and logs each complete line in real-time.
   426→type lineWriter struct {
   427→	logger *slog.Logger
   428→	cmd    string
   429→	level  slog.Level
   430→	buf    []byte
   431→	ring   *ringBuffer // optional; if set, also records lines for error reporting
   432→}
   433→
   434→func (w *lineWriter) Write(p []byte) (int, error) {
   435→	w.buf = append(w.buf, p...)
   436→	for {
   437→		idx := bytes.IndexByte(w.buf, '\n')
   438→		if idx < 0 {
   439→			break
   440→		}
   441→		line := strings.TrimRight(string(w.buf[:idx]), "\r")
   442→		w.buf = w.buf[idx+1:]
   443→		if line == "" {
   444→			continue
   445→		}
   446→		w.logger.Log(context.Background(), w.level, line, "cmd", w.cmd)
   447→		if w.ring != nil {
   448→			w.ring.add(line)
   449→		}
   450→	}
   451→	return len(p), nil
   452→}
   453→
   454→func (w *lineWriter) flush() {
   455→	if len(w.buf) == 0 {
   456→		return
   457→	}
   458→	line := strings.TrimRight(string(w.buf), "\r\n")
   459→	w.buf = nil
   460→	if line == "" {
   461→		return
   462→	}
   463→	w.logger.Log(context.Background(), w.level, line, "cmd", w.cmd)
   464→	if w.ring != nil {
   465→		w.ring.add(line)
   466→	}
   467→}
   468→
   469→// ringBuffer keeps the last N lines for error reporting.
   470→type ringBuffer struct {
   471→	lines []string
   472→	max   int
   473→}
   474→
   475→func newRingBuffer(max int) *ringBuffer {
   476→	return &ringBuffer{max: max}
   477→}
   478→
   479→func (r *ringBuffer) add(line string) {
   480→	r.lines = append(r.lines, line)
   481→	if len(r.lines) > r.max {
   482→		r.lines = r.lines[len(r.lines)-r.max:]
   483→	}
   484→}
   485→
   486→func (r *ringBuffer) get() []string {
   487→	return r.lines
   488→}
