    40→	}
    41→}
    42→
    43→// GitHubError represents an error response from the GitHub API.
    44→type GitHubError struct {
    45→	StatusCode int
    46→	Body       string
    47→}
    48→
    49→func (e *GitHubError) Error() string {
    50→	return fmt.Sprintf("github API: HTTP %d: %s", e.StatusCode, e.Body)
    51→}
    52→
    53→// Webhook represents a GitHub repository webhook.
    54→type Webhook struct {
    55→	ID     int64    `json:"id"`
    56→	Active bool     `json:"active"`
    57→	Config WHConfig `json:"config"`
    58→	Events []string `json:"events"`
    59→	URL    string   // extracted from Config.URL
    60→}
    61→
    62→// WHConfig is the webhook configuration object from the GitHub API.
    63→type WHConfig struct {
    64→	URL         string `json:"url"`
    65→	ContentType string `json:"content_type"`
    66→	Secret      string `json:"secret,omitempty"` // only set on create, never returned by API
    67→	InsecureSSL string `json:"insecure_ssl"`
    68→}
    69→
    70→// CreateWebhookRequest holds the parameters for creating a webhook.
    71→type CreateWebhookRequest struct {
    72→	URL    string
    73→	Secret string
    74→	Events []string
    75→}
    76→
    77→// SyncResult holds the outcome of syncing a single repo.
    78→type SyncResult struct {
    79→	Repo   string
    80→	Action string // "exists", "created", "error"
    81→	ID     int64
    82→	Error  error
    83→}
    84→
    85→// WebhookStatus is returned by ListWebhookStatuses.
