   139→// ListWebhooks returns all webhooks for a repository, following pagination.
   140→func (c *GitHubClient) ListWebhooks(ctx context.Context, owner, repo string) ([]Webhook, error) {
   141→	var all []Webhook
   142→	page := 1
   143→
   144→	for {
   145→		url := fmt.Sprintf("%s/repos/%s/%s/hooks?per_page=100&page=%d", c.BaseURL, owner, repo, page)
   146→		resp, err := c.doRequest(ctx, http.MethodGet, url, nil)
   147→		if err != nil {
   148→			return nil, err
   149→		}
   150→
   151→		body, err := io.ReadAll(resp.Body)
   152→		resp.Body.Close()
   153→		if err != nil {
   154→			return nil, fmt.Errorf("reading response body: %w", err)
   155→		}
   156→
   157→		if resp.StatusCode != http.StatusOK {
   158→			return nil, &GitHubError{StatusCode: resp.StatusCode, Body: string(body)}
   159→		}
   160→
   161→		var hooks []Webhook
   162→		if err := json.Unmarshal(body, &hooks); err != nil {
   163→			return nil, fmt.Errorf("decoding webhooks response: %w", err)
   164→		}
   165→
   166→		for i := range hooks {
   167→			hooks[i].URL = hooks[i].Config.URL
   168→		}
   169→
   170→		all = append(all, hooks...)
   171→
   172→		if !strings.Contains(resp.Header.Get("Link"), `rel="next"`) {
   173→			break
   174→		}
   175→		page++
   176→	}
   177→
   178→	return all, nil
   179→}
   180→
   181→// CreateWebhook creates a new webhook on the given repository.
   182→func (c *GitHubClient) CreateWebhook(ctx context.Context, owner, repo string, req CreateWebhookRequest) (*Webhook, error) {
   183→	url := fmt.Sprintf("%s/repos/%s/%s/hooks", c.BaseURL, owner, repo)
   184→
   185→	type createBody struct {
   186→		Name   string   `json:"name"`
   187→		Active bool     `json:"active"`
   188→		Events []string `json:"events"`
   189→		Config WHConfig `json:"config"`
   190→	}
   191→
   192→	payload := createBody{
   193→		Name:   "web",
   194→		Active: true,
   195→		Events: req.Events,
   196→		Config: WHConfig{
   197→			URL:         req.URL,
   198→			ContentType: "json",
   199→			Secret:      req.Secret,
   200→			InsecureSSL: "0",
   201→		},
   202→	}
   203→
   204→	resp, err := c.doRequest(ctx, http.MethodPost, url, payload)
   205→	if err != nil {
   206→		return nil, err
   207→	}
   208→
   209→	respBody, err := io.ReadAll(resp.Body)
   210→	resp.Body.Close()
   211→	if err != nil {
   212→		return nil, fmt.Errorf("reading response body: %w", err)
   213→	}
   214→
   215→	if resp.StatusCode != http.StatusCreated {
   216→		return nil, &GitHubError{StatusCode: resp.StatusCode, Body: string(respBody)}
   217→	}
   218→
   219→	var hook Webhook
   220→	if err := json.Unmarshal(respBody, &hook); err != nil {
   221→		return nil, fmt.Errorf("decoding create webhook response: %w", err)
   222→	}
   223→	hook.URL = hook.Config.URL
   224→
   225→	return &hook, nil
   226→}
   227→
   228→// DeleteWebhook deletes a webhook by ID.
   229→func (c *GitHubClient) DeleteWebhook(ctx context.Context, owner, repo string, id int64) error {
   230→	url := fmt.Sprintf("%s/repos/%s/%s/hooks/%d", c.BaseURL, owner, repo, id)
   231→
   232→	resp, err := c.doRequest(ctx, http.MethodDelete, url, nil)
   233→	if err != nil {
   234→		return err
   235→	}
   236→
   237→	body, err := io.ReadAll(resp.Body)
   238→	resp.Body.Close()
   239→	if err != nil {
   240→		return fmt.Errorf("reading response body: %w", err)
   241→	}
   242→
   243→	if resp.StatusCode != http.StatusNoContent {
   244→		return &GitHubError{StatusCode: resp.StatusCode, Body: string(body)}
   245→	}
   246→	return nil
   247→}
   248→
   249→// uniqueRepos returns a sorted, deduplicated list of repos referenced by config.Apps.
   250→func uniqueRepos(cfg *config.Config) []string {
   251→	repoSet := make(map[string]struct{})
   252→	for _, app := range cfg.Apps {
   253→		repoSet[app.Repo] = struct{}{}
   254→	}
   255→	return slices.Collect(maps.Keys(repoSet))
   256→}
   257→
   258→// splitRepo splits "owner/repo" into its two components.
   259→func splitRepo(fullRepo string) (string, string, error) {
   260→	parts := strings.SplitN(fullRepo, "/", 2)
   261→	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
   262→		return "", "", fmt.Errorf("invalid repo format %q, expected owner/repo", fullRepo)
   263→	}
   264→	return parts[0], parts[1], nil
   265→}
   266→
   267→// webhookURL returns the herald webhook URL derived from config.
   268→func webhookURL(cfg *config.Config) string {
   269→	return "https://" + cfg.Server.DeployDomain + "/webhook"
   270→}
   271→
   272→// eventsForRepo returns the events to subscribe to for a repo.
   273→// Subscribes to pull_request if any app referencing the repo has preview enabled.
   274→func eventsForRepo(cfg *config.Config, repo string) []string {
   275→	for _, app := range cfg.Apps {
   276→		if app.Repo == repo && app.Preview != nil && app.Preview.Enabled {
   277→			return []string{"push", "pull_request"}
   278→		}
   279→	}
   280→	return []string{"push"}
   281→}
   282→
   283→// formatAPIError wraps a GitHub API error with actionable messaging.
   284→func formatAPIError(repo string, err error) error {
   285→	var ghErr *GitHubError
   286→	if errors.As(err, &ghErr) && ghErr.StatusCode == http.StatusNotFound {
   287→		return fmt.Errorf("cannot manage webhooks for %q: ensure the token has 'admin:repo_hook' scope and access to this repository", repo)
   288→	}
   289→	return err
   290→}
   291→
   292→// SyncWebhooks ensures herald webhooks are registered on all repos referenced in config.
   293→func SyncWebhooks(ctx context.Context, cfg *config.Config, store *secrets.Store, client *GitHubClient) ([]SyncResult, error) {
   294→	webhookSecret, err := store.Get("herald/webhook_secret")
   295→	if err != nil {
   296→		return nil, fmt.Errorf("getting webhook secret: %w", err)
   297→	}
   298→
   299→	targetURL := webhookURL(cfg)
   300→	repos := uniqueRepos(cfg)
   301→	slices.Sort(repos)
   302→
   303→	results := make([]SyncResult, 0, len(repos))
   304→	for _, repoFull := range repos {
   305→		results = append(results, syncRepo(ctx, cfg, client, repoFull, targetURL, webhookSecret))
   306→	}
   307→
   308→	return results, nil
   309→}
   310→
   311→func syncRepo(ctx context.Context, cfg *config.Config, client *GitHubClient, repoFull, targetURL, webhookSecret string) SyncResult {
   312→	result := SyncResult{Repo: repoFull}
   313→
   314→	owner, repoName, err := splitRepo(repoFull)
   315→	if err != nil {
   316→		result.Action = "error"
   317→		result.Error = err
   318→		return result
   319→	}
   320→
   321→	hooks, err := client.ListWebhooks(ctx, owner, repoName)
   322→	if err != nil {
   323→		result.Action = "error"
   324→		result.Error = formatAPIError(repoFull, err)
   325→		return result
   326→	}
   327→
   328→	var heraldHook *Webhook
   329→	for i := range hooks {
   330→		if hooks[i].Config.URL == targetURL {
   331→			heraldHook = &hooks[i]
   332→			break
   333→		}
   334→	}
   335→
   336→	if heraldHook != nil && heraldHook.Active {
   337→		result.Action = "exists"
   338→		result.ID = heraldHook.ID
   339→		return result
   340→	}
   341→
   342→	// Delete inactive hook before recreating.
   343→	if heraldHook != nil {
   344→		if err := client.DeleteWebhook(ctx, owner, repoName, heraldHook.ID); err != nil {
   345→			result.Action = "error"
   346→			result.Error = formatAPIError(repoFull, err)
   347→			return result
   348→		}
   349→	}
   350→
   351→	hook, err := client.CreateWebhook(ctx, owner, repoName, CreateWebhookRequest{
   352→		URL:    targetURL,
   353→		Secret: webhookSecret,
   354→		Events: eventsForRepo(cfg, repoFull),
   355→	})
   356→	if err != nil {
   357→		result.Action = "error"
   358→		result.Error = formatAPIError(repoFull, err)
   359→		return result
   360→	}
   361→
   362→	result.Action = "created"
   363→	result.ID = hook.ID
   364→	return result
   365→}
   366→
   367→// ListWebhookStatuses returns the webhook status for each unique repo in config.
   368→func ListWebhookStatuses(ctx context.Context, cfg *config.Config, client *GitHubClient) []WebhookStatus {
   369→	targetURL := webhookURL(cfg)
   370→	repos := uniqueRepos(cfg)
   371→	slices.Sort(repos)
   372→
   373→	statuses := make([]WebhookStatus, 0, len(repos))
   374→	for _, repoFull := range repos {
   375→		status := WebhookStatus{Repo: repoFull}
   376→
   377→		owner, repoName, err := splitRepo(repoFull)
   378→		if err != nil {
   379→			statuses = append(statuses, status)
   380→			continue
   381→		}
   382→
   383→		hooks, err := client.ListWebhooks(ctx, owner, repoName)
   384→		if err != nil {
   385→			statuses = append(statuses, status)
   386→			continue
   387→		}
   388→
   389→		for _, hook := range hooks {
   390→			if hook.Config.URL == targetURL {
   391→				status.Found = true
   392→				status.URL = hook.Config.URL
   393→				status.Active = hook.Active
   394→				break
   395→			}
   396→		}
   397→
   398→		statuses = append(statuses, status)
   399→	}
   400→
   401→	return statuses
   402→}
