    97→// getIaCRepo reads the git remote URL from the IaC repo clone and returns the
    98→// GitHub full name (e.g. "nogo/srv2"), or "" if unavailable.
    99→func getIaCRepo(dataDir string) string {
   100→	repoDir := filepath.Join(dataDir, "repo")
   101→	out, err := exec.Command("git", "-C", repoDir, "remote", "get-url", "origin").Output()
   102→	if err != nil {
   103→		return ""
   104→	}
   105→	return parseGitHubRepo(strings.TrimSpace(string(out)))
   106→}
   107→
   108→// parseGitHubRepo extracts "owner/repo" from a GitHub clone URL.
   109→func parseGitHubRepo(rawURL string) string {
   110→	rawURL = strings.TrimSuffix(rawURL, ".git")
   111→	if after, ok := strings.CutPrefix(rawURL, "https://github.com/"); ok {
   112→		return after
   113→	}
   114→	// git@github.com:owner/repo
   115→	if idx := strings.Index(rawURL, "@github.com:"); idx >= 0 {
   116→		return rawURL[idx+len("@github.com:"):]
   117→	}
   118→	return ""
   119→}
