   121→// makeIaCPushHandler returns a function that triggers auto-deploy for stacks
   122→// with auto_deploy: true, and logs the rest.
   123→func makeIaCPushHandler(mgr *stacks.StackManager) func() {
   124→	return func() {
   125→		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Minute)
   126→		defer cancel()
   127→
   128→		for _, info := range mgr.List() {
   129→			if info.AutoDeploy {
   130→				slog.Info("IaC push: auto-deploying stack", "stack", info.Name)
   131→				if err := mgr.ComposeUp(ctx, info.Name); err != nil {
   132→					slog.Error("IaC push: auto-deploy failed", "stack", info.Name, "error", err)
   133→				} else {
   134→					slog.Info("IaC push: auto-deploy complete", "stack", info.Name)
   135→				}
   136→			} else {
   137→				slog.Info("IaC push: stack updated in repo (no auto-deploy)", "stack", info.Name)
   138→			}
   139→		}
   140→	}
   141→}
