   332→// detectServiceInfo parses a compose file to find the main service name and port.
   333→// Prefers a service named "app", then appName, then the first alphabetically.
   334→func detectServiceInfo(composeFilePath, appName string) (serviceName, port string, err error) {
   335→	data, err := os.ReadFile(composeFilePath)
   336→	if err != nil {
   337→		return "", "", err
   338→	}
   339→
   340→	var mc minimalCompose
   341→	if err := yaml.Unmarshal(data, &mc); err != nil {
   342→		return "", "", err
   343→	}
   344→
   345→	if len(mc.Services) == 0 {
   346→		return "app", "3000", nil
   347→	}
   348→
   349→	names := slices.Sorted(maps.Keys(mc.Services))
   350→	serviceName = names[0]
   351→	for _, n := range names {
   352→		if n == "app" || n == appName {
   353→			serviceName = n
   354→			break
   355→		}
   356→	}
   357→
   358→	port = extractFirstPort(mc.Services[serviceName])
   359→	if port == "" {
   360→		port = "3000"
   361→	}
   362→	return serviceName, port, nil
   363→}
   364→
   365→func extractFirstPort(svc minimalService) string {
   366→	for _, v := range svc.Expose {
   367→		if p := portFromAny(v); p != "" {
   368→			return p
   369→		}
   370→	}
   371→	for _, v := range svc.Ports {
   372→		if p := portFromAny(v); p != "" {
   373→			return p
   374→		}
   375→	}
   376→	return ""
   377→}
   378→
   379→func portFromAny(v any) string {
   380→	switch val := v.(type) {
   381→	case string:
   382→		// "3000", "3000:3000", "0.0.0.0:80:3000"
   383→		parts := strings.Split(val, ":")
   384→		p := strings.TrimSpace(parts[len(parts)-1])
   385→		return p
   386→	case int:
   387→		return fmt.Sprintf("%d", val)
   388→	case map[string]any:
   389→		// long form: {target: 3000, published: 3000}
   390→		if t, ok := val["target"]; ok {
   391→			return portFromAny(t)
   392→		}
   393→	}
   394→	return ""
   395→}
   396→
   397→// deepMerge recursively merges overlay into base. Overlay wins on conflict
   398→// unless both values are maps, in which case they are merged recursively.
   399→func deepMerge(base, overlay map[string]any) map[string]any {
   400→	result := make(map[string]any, len(base))
   401→	for k, v := range base {
   402→		result[k] = v
   403→	}
   404→	for k, v := range overlay {
   405→		if bv, ok := result[k]; ok {
   406→			if bMap, ok := bv.(map[string]any); ok {
   407→				if oMap, ok := v.(map[string]any); ok {
   408→					result[k] = deepMerge(bMap, oMap)
   409→					continue
   410→				}
   411→			}
   412→		}
   413→		result[k] = v
   414→	}
   415→	return result
   416→}
   417→
   418→// ensureCaddyNetwork creates the caddy Docker network if it doesn't exist.
   419→func ensureCaddyNetwork(ctx context.Context, logger *slog.Logger) error {
   420→	cmd := exec.CommandContext(ctx, "docker", "network", "inspect", "caddy")
   421→	if err := cmd.Run(); err == nil {
   422→		return nil
   423→	}
   424→	return runCmd(ctx, logger, "", "docker", "network", "create", "caddy")
   425→}
   426→
   427→// runCompose executes docker compose up -d --build --remove-orphans.
   428→func (d *Deployer) runCompose(ctx context.Context, appDir, appName, composeFile string) error {
   429→	repoDir := filepath.Join(appDir, "repo")
   430→	overrideFile := filepath.Join(appDir, "compose.override.yml")
   431→	d.Logger.Info("compose up", "app", appName, "project", "herald-"+appName)
   432→	return runCmd(ctx, d.Logger, repoDir,
   433→		"docker", "compose",
   434→		"--project-name", "herald-"+appName,
   435→		"-f", composeFile,
   436→		"-f", overrideFile,
   437→		"up", "-d", "--build", "--remove-orphans",
   438→	)
   439→}
   440→
   441→// runCmd executes a command, logs stdout/stderr line-by-line, and returns an
   442→// error on non-zero exit.
   443→func runCmd(ctx context.Context, logger *slog.Logger, dir string, name string, args ...string) error {
   444→	cmd := exec.CommandContext(ctx, name, args...)
   445→	if dir != "" {
   446→		cmd.Dir = dir
   447→	}
   448→
   449→	var stdout, stderr bytes.Buffer
   450→	cmd.Stdout = &stdout
   451→	cmd.Stderr = &stderr
   452→
   453→	start := time.Now()
   454→	runErr := cmd.Run()
   455→	dur := time.Since(start).Round(time.Millisecond)
   456→
   457→	logLines := func(output string, level slog.Level) {
   458→		for line := range strings.Lines(output) {
   459→			line = strings.TrimRight(line, "\n\r")
   460→			if line != "" {
   461→				logger.Log(ctx, level, line, "cmd", name)
   462→			}
   463→		}
   464→	}
   465→
   466→	logLines(stdout.String(), slog.LevelInfo)
   467→	if stderr.Len() > 0 {
   468→		logLines(stderr.String(), slog.LevelWarn)
   469→	}
   470→
   471→	if runErr != nil {
   472→		return fmt.Errorf("%s: %w (duration: %s)", name, runErr, dur)
   473→	}
   474→
   475→	logger.Info("command completed", "cmd", name, "duration", dur)
   476→	return nil
   477→}
